-- Leaderboard for Are You a LARPer?
-- Run once in the Supabase dashboard: SQL Editor -> New query -> paste -> Run.

create table if not exists public.scores (
  id uuid primary key default gen_random_uuid(),
  -- Generated by the browser when a game starts; one row per game.
  game_id uuid not null unique,
  username text not null check (char_length(btrim(username)) between 1 and 20),
  score integer not null check (score between 0 and 2000), -- 100 picks x 20 pts max
  named integer not null check (named between 0 and 100),
  time_ms integer not null check (time_ms between 0 and 900000), -- 15 min limit
  verdict text not null check (char_length(verdict) <= 30),
  created_at timestamptz not null default now(),
  check (score <= named * 20)
);

create index if not exists scores_rank_idx on public.scores (score desc, time_ms asc);

-- The site uses the public anon key, so access is controlled here: anyone can
-- read the board and add a finished game, nobody can edit or delete rows.
alter table public.scores enable row level security;

drop policy if exists "Anyone can read scores" on public.scores;
create policy "Anyone can read scores" on public.scores
  for select to anon, authenticated using (true);

drop policy if exists "Anyone can submit a score" on public.scores;
create policy "Anyone can submit a score" on public.scores
  for insert to anon, authenticated with check (true);
